#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""Convert .tflite model files to a C header containing a uint8_t[] array.

Output format (single .h, xxd-style):
    // Auto-generated from <input.tflite>
    alignas(8) const unsigned char g_model_<NAME>[] = { 0x..., 0x..., ... };
    const unsigned int g_model_<NAME>_len = <SIZE>;

Where <NAME> is derived from --name (default: input basename without .tflite).
The header is wrapped in extern "C" so it can be included from both C and C++.

Usage:
    python MCU/scripts/tflite_to_c_array.py --tflite model_v4_se_23dim_ch32_qat_s42_int8.tflite --out MCU/Core/Inc/model_data_qat_s42.h
    python MCU/scripts/tflite_to_c_array.py --all --src . --dst MCU/Core/Inc
"""

import argparse
import os
import re
import sys


HEADER_TEMPLATE = '''/* ============================================================================
 * Auto-generated by MCU/scripts/tflite_to_c_array.py
 * Source: {src}
 * Size:   {size} bytes ({size_kb:.2f} KB)
 * DO NOT EDIT BY HAND.
 * ============================================================================
 */
#ifndef MODEL_{guard}_H_
#define MODEL_{guard}_H_

#include <stdint.h>

/* 跨 C/C++ 兼容的 8 字节对齐宏. AC6 armclang 用 alignas (C++), __attribute__ (C).
 * TFLite Micro MicroInterpreter 不要求 8 字节对齐, 这里是性能优化. */
#ifdef __cplusplus
  #define _TFLM_MODEL_ALIGNAS_8 alignas(8)
#else
  #define _TFLM_MODEL_ALIGNAS_8 __attribute__((aligned(8)))
#endif

#ifdef __cplusplus
extern "C" {{
#endif

_TFLM_MODEL_ALIGNAS_8 const unsigned char g_model_{name}[] = {{
{array_body}
}};

const unsigned int g_model_{name}_len = {size};

#ifdef __cplusplus
}}
#endif

#endif /* MODEL_{guard}_H_ */
'''


def bytes_to_c_array(data: bytes, per_line: int = 16) -> str:
    """Format bytes as 0xNN entries, `per_line` per line."""
    lines = []
    for i in range(0, len(data), per_line):
        chunk = data[i:i + per_line]
        hex_str = ", ".join("0x{:02x}".format(b) for b in chunk)
        lines.append("    " + hex_str + ",")
    return "\n".join(lines)


def sanitize_name(name: str) -> str:
    """Map arbitrary filename stem to a C-safe identifier."""
    s = re.sub(r"[^A-Za-z0-9_]", "_", name)
    if s and s[0].isdigit():
        s = "_" + s
    return s


def convert_one(tflite_path: str, out_path: str, name: str | None = None) -> int:
    with open(tflite_path, "rb") as f:
        data = f.read()
    size = len(data)
    if name is None:
        name = sanitize_name(os.path.splitext(os.path.basename(tflite_path))[0])
    guard = re.sub(r"[^A-Za-z0-9_]", "_", name).upper()
    body = bytes_to_c_array(data)
    header = HEADER_TEMPLATE.format(
        src=tflite_path,
        size=size,
        size_kb=size / 1024.0,
        name=name,
        guard=guard,
        array_body=body,
    )
    os.makedirs(os.path.dirname(out_path) or ".", exist_ok=True)
    with open(out_path, "w", encoding="utf-8") as f:
        f.write(header)
    return size


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--tflite", help="single .tflite to convert")
    parser.add_argument("--out", help="output .h path (when --tflite used)")
    parser.add_argument("--name", default=None,
                        help="identifier name (default = input basename without ext)")
    parser.add_argument("--all", action="store_true",
                        help="batch convert all 5 seeds: model_v4_se_23dim_ch32_qat_s{42,123,456,789,1024}_int8.tflite")
    parser.add_argument("--src", default=".",
                        help="source directory for --all (default: .)")
    parser.add_argument("--dst", default="MCU/Core/Inc",
                        help="destination directory for --all (default: MCU/Core/Inc)")
    args = parser.parse_args()

    if not args.all and not args.tflite:
        parser.error("Either --tflite or --all required")
    if args.all and args.tflite:
        parser.error("--all and --tflite are mutually exclusive")

    if args.all:
        seeds = [42, 123, 456, 789, 1024]
        total = 0
        for s in seeds:
            tflite = os.path.join(args.src, f"model_v4_se_23dim_ch32_qat_s{s}_int8.tflite")
            if not os.path.exists(tflite):
                print(f"[skip] {tflite} not found", file=sys.stderr)
                continue
            out = os.path.join(args.dst, f"model_data_qat_s{s}.h")
            n = convert_one(tflite, out, name=f"v4_se_23dim_ch32_qat_s{s}")
            print(f"[ok] {tflite} -> {out} ({n} bytes / {n/1024:.2f} KB)")
            total += n
        print(f"[done] total {total} bytes / {total/1024:.2f} KB across 5 seeds")
        return 0

    if not args.out:
        parser.error("--out required when --tflite is set")
    n = convert_one(args.tflite, args.out, name=args.name)
    print(f"[ok] {args.tflite} -> {args.out} ({n} bytes / {n/1024:.2f} KB)")
    return 0


if __name__ == "__main__":
    sys.exit(main())
